em:{from:"Omar", to:"Theo", subj:"Internet for the new place",
body:`Hi Theo,

I've been looking into internet for the new apartment. Between you uploading those huge video files for work and me gaming every evening, the cheapest plan is out of the question. Its [[1]] would be used up within a couple of weeks.

I was leaning toward Stream 300. It's just as fast as the Flex version but costs [[2]] less each month. The catch is that it would lock us in for two years, and our lease ends in twelve months. We could go with Flex instead, but then we'd have to pay [[3]] just to have it installed.

I don't think we need Gigabit. It's the fastest, but it costs [[4]] as much as Basic 50, and neither of us needs that kind of speed.

If we do sign a contract, remember the new-customer deal: [[5]] for the first three months.

Let me know which one you'd rather go with before Friday, because installation takes a week to book.

Omar`},
