em:{from:"Greg", to:"Anita", subj:"Moving company",
body:`Anita,

I got the Swift Hands brochure. Since the kids start their new school on Monday, the move has to happen on Saturday, which means the hourly packages would [[1]].

I'd rule out Basic Crew. We have that enormous wardrobe and the bunk beds, which would need to be [[2]], and Basic Crew doesn't do that.

Full Service is tempting because we wouldn't have to [[3]], and you've been working overtime all month.

Also, the new house won't be ready until the 15th, so we'll need somewhere to keep our things for two weeks. With Full Service, [[4]].

Whatever we choose, remember to budget [[5]] for Grandma's piano.

Let me know what you think.

Greg`},
