em:{from:"Amir", to:"Jess", subj:"Your bike",
body:`Hi Jess,

I took a look at the Spoke & Chain packages for your bike. You mentioned that your back wheel wobbles, so the Basic Tune-Up won't be enough. You'll need at least the [[1]].

Since you need the bike for the charity ride next Saturday, and it's Monday now, you'd have enough time if you drop it off [[2]].

Remember that your front tire has a hole in it, and a new tire would [[3]].

The Overhaul sounds great, but it takes [[4]], so it wouldn't be ready in time.

Also, since you live only three kilometres away, they'll [[5]].

Amir`},
b:[
[["Full Tune-Up","Basic Tune-Up","Overhaul","rush service"],"Wheel straightening","A wobbly wheel needs straightening, which is in the Full Tune-Up."],
[["by Tuesday","on Friday","next Saturday","in two weeks"],"Ready in 4 days","Four days from Tuesday is Saturday at the latest."],
[["cost extra","be free","take a week","be included"],"Parts not included (e.g., new tires, chains).","Tires are parts, which are not included."],
[["a full week","two days","four days","one day"],"Ready in 7 days","The Overhaul takes 7 days."],
[["pick it up for free","charge $30","deliver it the same day","replace the tire"],"Free pickup within 5 km of the shop.","Three kilometres is within 5 km."]
],
