art:{h:"Is cash disappearing?",
text:`More Canadians are paying with cards and phones instead of cash. Some stores and cafés no longer accept cash at all.

Café owner Ben Taylor stopped taking cash last year. 'It's faster, and I don't have to go to the bank every day,' he said. He says most of his customers didn't mind.

Senior Helen Moore is not happy about the change. She doesn't have a smartphone and prefers to use cash. 'I like to know exactly how much I'm spending,' she said. 'It's easy to spend too much with a card.'

Bank expert Raj Patel says cash is still important. 'If the internet stops working, card machines can't work,' he said. He thinks stores should accept both cash and cards.`},
