art:{h:"Bike lanes on Main Street: good or bad?",
text:`Last summer, the city added bike lanes on Main Street. To make space, it removed one lane for cars. Now people are sharing their opinions.

Cyclist Emma Brooks rides to work every day. 'Before the bike lanes, I was scared of the traffic,' she said. 'Now I feel much safer.' She says more people are cycling on Main Street now.

Taxi driver Ahmed Ali is not happy. He says traffic is slower because there is one less lane for cars. 'A trip that took ten minutes now takes twenty,' he said.

Shop owner Julie Martin says her business has not changed much. 'Some customers come by bike now, and some still drive,' she said. She would like the city to add more bike racks in front of her shop.`},
